const body = $input.first().json.body || $input.first().json;
const required = ['application_id', 'candidate_name', 'job_title', 'cv_text'];
for (const key of required) if (!body[key]) throw new Error(`Missing ${key}`);
const skillList = (body.required_skills || []).map(s => `- ${s.skill}: weight ${s.weight}%`).join('
');
const prompt = `Screen this CV for the job below. Score every required skill from 0 to 100. Return only JSON with ai_score (0-100), ai_confidence (low|medium|high), ai_recommendation (shortlist|review|reject), narrative_summary, and skill_scores [{skill,weight,score}].

Candidate: ${body.candidate_name}
Job: ${body.job_title}
Criteria: ${body.screening_criteria || 'N/A'}
Required skills:
${skillList}

CV:
${body.cv_text}`;
return [{ json: { application_id: body.application_id, geminiBody: { contents: [{ parts: [{ text: prompt }] }], generationConfig: { responseMimeType: 'application/json' } } } }];

const raw = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text;
if (!raw) throw new Error('Gemini returned no screening result');
const result = JSON.parse(raw);
const application_id = $('Prepare CV screening prompt').first().json.application_id;
return [{ json: { application_id, ai_score: Math.max(0, Math.min(100, Math.round(Number(result.ai_score) || 0))), ai_confidence: ['low','medium','high'].includes(result.ai_confidence) ? result.ai_confidence : 'medium', ai_recommendation: ['shortlist','review','reject'].includes(result.ai_recommendation) ? result.ai_recommendation : 'review', skill_scores: Array.isArray(result.skill_scores) ? result.skill_scores : [], narrative_summary: String(result.narrative_summary || ''), status: 'ai_screened' } }];
